class Solution {
public:
    string alphabetBoardPath(string target) {
        string answer;
        int row = 0, col = 0;
        for (char ch : target) {
            int nr = (ch - 'a') / 5, nc = (ch - 'a') % 5;
            while (row > nr) { answer += 'U'; --row; }
            while (col > nc) { answer += 'L'; --col; }
            while (row < nr) { answer += 'D'; ++row; }
            while (col < nc) { answer += 'R'; ++col; }
            answer += '!';
        }
        return answer;
    }
};
